class Animal:
    def __init__(self, name, species):
        self.name = name
        self.species = species

    def describe(self):
        return f'{self.name} the {self.species}'


class Bird(Animal):
    def __init__(self, name, species, wingspan):
        super().__init__(name, species)
        self.wingspan = wingspan

    def describe(self):
        return f'{super().describe()}, wingspan {self.wingspan} cm'


class Keeper:
    def __init__(self, name):
        self.name = name
        self.animals = []

    def adopt(self, animal):
        self.animals.append(animal)

    def feed_all(self):
        return [f'{animal.name} is fed' for animal in self.animals]


class Registry:
    def __init__(self):
        self.animals = []
        self.log = []

    def arrive(self, animal):
        for existing in self.animals:
            if existing.name == animal.name:
                raise ValueError(f'{animal.name} is already registered')
        self.animals.append(animal)
        self.log.append(f'{animal.name} arrived')

    def find(self, name):
        for animal in self.animals:
            if animal.name == name:
                return animal
        return None


def test_registry():
    registry = Registry()
    sly = Animal('Sly', 'fox')
    registry.arrive(sly)
    assert registry.find('Sly') is sly
    assert registry.find('Rusty') is None
    try:
        registry.arrive(Animal('Sly', 'fox'))
        assert False
    except ValueError:
        pass

